110	/**
111	 * Pure, unit-testable builder. For each ENABLED route with an active host port and
112	 * a resolvable manifest, emit one discovery row. Disabled routes, routes without a
113	 * host port, and routes whose manifest cannot be resolved are excluded. `complete`
114	 * is true only when every enabled route was inspected without an unrecoverable
115	 * error. `readManifest` is injectable so tests can drive it without on-disk agents;
116	 * it defaults to the exported readEnabledAgentManifest (hostPath + enabled-agent
117	 * fallback, never route.manifestPath).
118	 */
119	export function buildOpenAiAgentDiscovery({ routes = {}, readManifest = readEnabledAgentManifest } = {}) {
120	    const agents = [];
121	    let complete = true;
122	
123	    for (const [routeKey, route] of Object.entries(routes || {})) {
124	        if (!route || route.disabled || route.draining) continue;
125	        if (!isActiveHostPort(route.hostPort)) continue;
126	        let manifest = null;
127	        try {
128	            manifest = readManifest(routeKey, routes);
129	        } catch (_) {
130	            // A single route that throws during manifest resolution is an
131	            // unrecoverable discovery error: report it but keep going so the rest
132	            // of the inventory is still returned.
133	            complete = false;
134	            continue;
135	        }
136	        if (!manifest || typeof manifest !== 'object') continue;
137	        const row = buildAgentRow(routeKey, route, manifest);
138	        if (row) agents.push(row);
139	    }
140	
141	    return { complete, agents };
142	}
