207	        // caller probe why its assertion was rejected.
208	        sendJson(res, 401, { complete: false, error: 'agent_assertion_required' });
209	        return true;
210	    }
211	
212	    const routes = routing?.routes && typeof routing.routes === 'object' ? routing.routes : {};
213	    const result = buildOpenAiAgentDiscovery({ routes });
214	    sendJson(res, 200, result);
