    child.stdout.on('data', chunk => {
        stdoutBytes += chunk.length;
        stdoutTail = (stdoutTail + chunk.toString('latin1')).slice(-64);
        res.write(chunk);
    });
    child.stderr.on('data', chunk => {
        stderrChunks.push(chunk);
    });
